def chain_chain(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict[chain[0]]
    result = []

    while current:
        result.append(current[0])
        next_token = current[1]
        current = chain_dict[next_token]

    return ','.join(result)

# Example usage:
# print(chain_chain(['qic', 'ldh']))  # Output: qic, ldh
